#include <iostream>

int main()
{
    int score{};
    if (!(std::cin >> score)) return 0;

    if (score < 0 || score > 100)
        std::cout << "invalid\n";
    else if (score >= 70)
        std::cout << "distinction\n";
    else if (score >= 60)
        std::cout << "merit\n";
    else if (score >= 40)
        std::cout << "pass\n";
    else
        std::cout << "fail\n";

    return 0;
}
